    @Test
    @DisplayName("并发同 requestId 创建退役单：仅生效一次，全部重放同一成功结果")
    void concurrentSameRequestIdCreateRetirement() throws Exception {
        long docId = createDocument(newRequestId(), "[\"en\"]",
